/** 外部書類・秘密を含まない合成instance。 */
export const period = { startDate: "2024-04-01", endDate: "2025-03-31" };
export const context = (id = "current", members = "", dates = period) => `<xbrli:context id="${id}"><xbrli:entity><xbrli:identifier scheme="synthetic">TEST</xbrli:identifier></xbrli:entity><xbrli:period><xbrli:startDate>${dates.startDate}</xbrli:startDate><xbrli:endDate>${dates.endDate}</xbrli:endDate></xbrli:period>${members ? `<xbrli:scenario>${members}</xbrli:scenario>` : ""}</xbrli:context>`;
export const fact = (raw = "123.4500", attrs = "", key = "jppfs_cor:NetSales", contextRef = "current") => `<${key} contextRef="${contextRef}" unitRef="money" decimals="INF" ${attrs}>${raw}</${key}>`;
export const instance = (facts = fact(), contexts = context(), units = '<xbrli:unit id="money"><xbrli:measure>iso4217:JPY</xbrli:measure></xbrli:unit>') => `<xbrli:xbrl xmlns:xbrli="http://www.xbrl.org/2003/instance" xmlns:xbrldi="http://xbrl.org/2006/xbrldi" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:iso4217="http://www.xbrl.org/2003/iso4217" xmlns:jppfs_cor="http://disclosure.edinet-fsa.go.jp/taxonomy/jppfs/2024-11-01/jppfs_cor" xmlns:jpcrp_cor="http://disclosure.edinet-fsa.go.jp/taxonomy/jpcrp/2024-11-01/jpcrp_cor" xmlns:extension="https://example.test/extension">${contexts}${units}${facts}</xbrli:xbrl>`;
export const standalone = '<xbrldi:explicitMember dimension="jppfs_cor:ConsolidatedOrNonConsolidatedAxis">jppfs_cor:NonConsolidatedMember</xbrldi:explicitMember>';
